INSERT INTO posts (
user_id, title, subtitle, price, discount_rate, duration,
max_participants, rating, review_count, like_count,
city_name, country, lat, lng
)
VALUES (
#{user_id}, #{title}, #{subtitle}, #{price}, #{discount_rate}, #{duration},
#{max_participants}, #{rating}, #{review_count}, #{like_count},
#{city_name}, #{country}, #{lat}, #{lng}
)

mapper.select:
SELECT DISTINCT p.post_id, p.user_id, p.title, p.subtitle, p.price, p.discount_rate, p.duration, p.max_participants, p.rating, p.review_count, p.like_count, p.city_name, p.country, p.lat, p.lng, p.created_at, p.updated_at FROM posts p LEFT JOIN post_tags t ON p.post_id = t.post_id
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.subtitle LIKE CONCAT('%', #{keyword}, '%') OR t.tag_name LIKE CONCAT('%', #{keyword}, '%'))
AND p.city_name = #{city}
AND p.country = #{country}
AND p.user_id = #{userId}
ORDER BY p.post_id DESC

SELECT lang_code AS langCode, tag_name AS tagName
FROM post_tags
WHERE post_id = #{postId}
